  "aitext.improve": "Verbessern",
  "aitext.improve.prompt": "Verbessere den Text: klarer, flüssiger und präziser formuliert, gleicher Inhalt, ähnliche Länge. Behalte die Sprache des Textes bei.",
  "aitext.shorten": "Kürzen",
