  "nav.security": "Sicherheit",
  "sec.title": "Sicherheit",
  "sec.intro": "Verschlüsselung der Datenbank und App-Sperre. Beides ist aus, bis du es einschaltest.",
  "sec.db.title": "Datenbankverschlüsselung",
  "sec.db.desc": "Verschlüsselt die Datenbank mit deinen Notizen, Aufgaben und Zeiten (AES-256, SQLCipher). Der Schlüssel liegt im Schlüsselspeicher dieses Rechners.",
  "sec.db.state": "Verschlüsselung",
  "sec.db.on": "Verschlüsselt",
  "sec.db.off": "Nicht verschlüsselt",
  "sec.db.onDesc": "Die Datenbank und ihre Sicherungen sind verschlüsselt.",
  "sec.db.offDesc": "Die Datenbank ist eine normale SQLite-Datei, die jedes Programm lesen kann.",
  "sec.db.encrypt": "Datenbank verschlüsseln…",
  "sec.db.decrypt": "Entschlüsseln…",
  "sec.db.fileStore": "Auf diesem Rechner gibt es keinen Schlüsselbund (Secret Service). Der Schlüssel liegt deshalb in einer Datei im App-Datenordner, nur für deinen Benutzer lesbar. Die Verschlüsselung schützt dann vor allem Kopien und Sicherungen der Datenbank, nicht vor jemandem mit Zugriff auf dein Benutzerkonto.",
  "sec.db.portable": "Portabler Modus: Der Schlüssel liegt im Schlüsselspeicher dieses Rechners, nicht auf dem Datenträger. Auf anderen Rechnern öffnet Arcalo die Daten nur mit dem Wiederherstellungsschlüssel – oder mit einem Passwort, wenn du den Schlüssel unten damit schützt.",
  "sec.db.old": "Vorherige Datenbankdatei",
  "sec.db.oldDesc": "Die Datei vor der Umstellung wird zur Sicherheit bis zum nächsten Start aufbewahrt und dann überschrieben und gelöscht.",
  "sec.db.oldDrop": "Jetzt sicher löschen",
  "sec.db.oldFailed": "Löschen fehlgeschlagen",
  "sec.db.plainBackups": "Ältere Sicherungen",
  "sec.db.plainBackupsDesc": { one: "{n} lokale Sicherung stammt von vor der Verschlüsselung und ist unverschlüsselt. Kopien in Sicherungszielen bleiben, bis sie dort rotiert werden.", other: "{n} lokale Sicherungen stammen von vor der Verschlüsselung und sind unverschlüsselt. Kopien in Sicherungszielen bleiben, bis sie dort rotiert werden." },
  "sec.db.plainDrop": "Unverschlüsselte löschen",
  "sec.db.plainDropped": { one: "{n} Sicherung gelöscht", other: "{n} Sicherungen gelöscht" },
  "sec.db.mirror": "Markdown-Spiegel",
  "sec.db.mirrorDesc": "Bleibt unverschlüsselt: Der Spiegel schreibt jede Seite als lesbare Markdown-Datei. Schalte ihn aus, wenn nichts im Klartext auf dem Datenträger liegen soll.",
  "sec.db.mirrorGitDesc": "Bleibt unverschlüsselt: Der Spiegel und die Git-Synchronisierung schreiben jede Seite als lesbare Markdown-Datei, auch ins Git-Repository. Schalte ihn aus, wenn nichts im Klartext liegen soll.",
  "sec.db.mirrorLink": "Einstellungen",
  "sec.db.attachments": "Anhänge",
  "sec.db.attachmentsDesc": "Bilder, PDFs und andere Dateien liegen als normale Dateien im Ordner „attachments“ und werden nicht verschlüsselt.",
  "sec.db.unencrypted": "unverschlüsselt",
  "sec.db.recovery": "Wiederherstellungsschlüssel",
  "sec.db.recoveryDesc": "Öffnet die Datenbank und ihre Sicherungen, wenn der Schlüssel auf einem Rechner fehlt (neuer Laptop, wiederhergestelltes Abbild).",
  "sec.db.recoveryShow": "Anzeigen…",
  "sec.db.password": "Schlüssel mit Passwort schützen",
  "sec.db.passwordDesc": "Legt den Schlüssel zusätzlich mit einem Passwort geschützt (Argon2id) in den Datenordner. Damit öffnet ein portables Arcalo auch auf anderen Rechnern – mit dem Passwort statt dem Wiederherstellungsschlüssel.",
  "sec.db.rekey": "Schlüssel wechseln",
  "sec.db.rekeyDesc": "Verschlüsselt die Datenbank mit einem neuen Schlüssel, ohne sie zu entschlüsseln – etwa wenn der Wiederherstellungsschlüssel in falsche Hände geraten sein könnte.",
  "sec.db.rekeyButton": "Schlüssel wechseln …",
  "sec.db.passwordOn": "Ein Passwort ist eingerichtet: Auf Rechnern ohne Schlüssel öffnet Arcalo mit dem Passwort oder dem Wiederherstellungsschlüssel.",
  "sec.db.passwordSet": "Passwort festlegen…",
  "sec.db.passwordRemove": "Passwort entfernen",
  "sec.db.passwordFailed": "Passwort nicht gespeichert",
  "sec.db.store": "Schlüsselspeicher",
  "sec.db.storeDesc": "Wo der Datenbankschlüssel und der PIN-Hash liegen.",
  "sec.enc.title": "Datenbank verschlüsseln",
  "sec.enc.text": "Arcalo erzeugt einen zufälligen Schlüssel, legt ihn im Schlüsselspeicher dieses Rechners ab und schreibt die Datenbank verschlüsselt neu.",
  "sec.enc.what": "Verschlüsselt: Notizen, Aufgaben, Zeiten, Einstellungen und alle neuen Sicherungen.",
  "sec.enc.notMirror": "Nicht verschlüsselt: der Markdown-Spiegel und die Git-Synchronisierung (lesbare Dateien).",
  "sec.enc.notAttachments": "Nicht verschlüsselt: Anhänge wie Bilder und PDFs.",
  "sec.enc.backups": "Ältere Sicherungen bleiben unverschlüsselt; du kannst sie danach löschen.",
  "sec.enc.restart": "Arcalo startet dafür einmal neu. Die Umstellung wird geprüft und ist bei einem Abbruch sicher.",
  "sec.enc.next": "Weiter",
  "sec.enc.go": "Verschlüsseln und neu starten",
  "sec.rk.title": "Schlüssel wechseln",
  "sec.rk.text": "Arcalo verschlüsselt die Datenbank mit einem neuen Schlüssel. Dafür bekommst du einen neuen Wiederherstellungsschlüssel.",
  "sec.rk.oldInvalid": "Der bisherige Wiederherstellungsschlüssel öffnet die Datenbank danach nicht mehr.",
  "sec.rk.backups": "Sicherungen ab dem Wechsel nutzen den neuen Schlüssel. Ältere Sicherungen bleiben mit dem alten verschlüsselt – bewahre den alten Wiederherstellungsschlüssel auf, solange du sie brauchst.",
  "sec.rk.safe": "Die Datenbank wird dabei nie unverschlüsselt geschrieben. Bricht der Wechsel ab (Absturz, Stromausfall), öffnet Arcalo den bisherigen oder den neuen Stand – nie einen halben.",
  "sec.rk.restart": "Arcalo startet dafür einmal neu; offene Notizen werden vorher gespeichert.",
  "sec.rk.keyText": "Dein neuer Wiederherstellungsschlüssel. Drucke oder speichere ihn jetzt: Nach dem Neustart gilt nur noch er.",
