  "sec.rk.password": "Passwort des Schlüssels",
  "sec.rk.passwordHint": "Der neue Schlüssel wird mit demselben Passwort geschützt.",
  "sec.rk.go": "Schlüssel wechseln und neu starten",
  "sec.dec.title": "Verschlüsselung entfernen?",
  "sec.dec.text": "Arcalo startet neu und schreibt die Datenbank wieder unverschlüsselt. Der Schlüssel bleibt im Schlüsselspeicher, damit ältere verschlüsselte Sicherungen lesbar bleiben.",
